"""Writes docs/REPORT_FACTS.md from the measured JSON files. Run from 8.ProjectCode:  python -m scripts.docs.make_report_facts"""
import json
import os

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
EXP = os.path.join(ROOT, "experiments")


def J(*p):
    return json.load(open(os.path.join(EXP, *p), encoding="utf-8"))


def pm(d, k, n=4):
    return f"{d[k]['mean']:.{n}f} ± {d[k]['std']:.{n}f}"


off, pap, sh = J("unsw_nb15", "official", "metrics.json"), J("unsw_nb15", "paper_protocol", "metrics.json"), J("unsw_nb15", "shift", "metrics.json")
cry, pipe = J("crypto", "metrics.json"), J("pipeline", "metrics.json")
shipped = json.load(open(os.path.join(ROOT, "reports", "metrics.json")))
L = []
w = L.append

w("# REPORT_FACTS - CipherGuard Shield (CSE-A-A5)\n")
w("Single source of truth for the documentation build. Every number below was produced by a script in `scripts/` and is stored as JSON under `experiments/` (or `reports/`). Generated by `python -m scripts.docs.make_report_facts`.\n")
w("## 1. Project and team\n")
w("- Title: Secure Data Transmission in Cloud Computing using Encryption and Machine Learning. Product: **CipherGuard Shield** (SecureChannel + ThreatSense Engine + live console). Batch CSE-A-A5. Ports: API 8305, console 5305.")
w("- Students: AVUTI SANDHYA 23K91A0520; BANOTHU INDU 23K91A0530; DASARI SRITEJA 23K91A0559; BEJUGAM VAISHNAVI 23K91A0533. Guide: CH.PRABHAKAR (designation unknown -> placeholder).")
w("- Base paper: V. Kalyanasundaram, S. Raja, S. Kanthimathi, \"Intrusion Detection Model Using Fused Quantum NN-LeNet With Improved Elliptic Curve Cryptography Based Data Security,\" IEEE Access, vol. 14, pp. 63767-63779, 2026, doi 10.1109/ACCESS.2026.3686106 (PDF in 8.ProjectCode).")
w("- Batch objectives (6.OBJECTIVES): hybrid AES + RSA scheme; key generation/distribution; encrypt-before-upload / decrypt-after-download module; ML classifier on a benchmark intrusion dataset; flag + log suspicious sessions; evaluate enc/dec time, throughput overhead and detection accuracy.")
w("- **Deviation to state plainly:** the product uses **ECDH P-256 + HKDF-SHA256 + AES-256-GCM**, not RSA. RSA-2048/3072-OAEP + AES-256-GCM hybrid was implemented only as a *benchmark baseline* (scripts/benchmark_crypto.py), not in the product.\n")

w("## 2. Architecture and code\n")
w("- Python 3.11.9, FastAPI 0.110 (requirements pin) with uvicorn, `cryptography` 42.0.7, XGBoost 2.0.3, scikit-learn 1.5.0, PyTorch (requirements pin 2.2.0; 2.14.1+cpu on the machine used for measurement), pandas 2.2.1, numpy 1.26.4. Front end: React 19 + Vite 8 + Tailwind 4 + Recharts + three.js ('Kinetic Mono' V5 kit); legacy dashboard in `web/` (plain HTML/JS).")
w("- Modules: `cipherguard/crypto/secure_channel.py` (160 lines: KeyPair, SecureChannel: derive_session_key, encrypt, decrypt, encrypt_with_ephemeral); `cipherguard/ids/` features.py (42-feature schema), preprocessing.py (ColumnTransformer: MinMaxScaler on 39 numeric + OneHotEncoder on proto/service/state), synthetic.py (generator), train.py (XGBoost + CNN + LR stacking), inference.py (ThreatSenseEngine); `cipherguard/api/main.py` (382 lines).")
w("- Model: XGBoost (200 trees, depth 6, lr 0.08, subsample/colsample 0.85, scale_pos_weight = neg/pos) + 1D CNN (Conv1d 1->32 k3, MaxPool2, Conv1d 32->64 k3, MaxPool2, Linear->64, Dropout 0.3, Linear->1, sigmoid; Adam 1e-3, batch 256, <=15 epochs, early stopping patience 5; **plain BCE loss - class weighting exists only in the TensorFlow branch, which was not used**) + Logistic Regression meta-model fitted on the validation split's [p_xgb, p_cnn]. Decision threshold 0.5. Severity bands on stacked probability: >=0.85 critical, >=0.70 high, else medium (normal = low).")
w("- Encoded input: 70 dims for the synthetic bundle (39 numeric + 31 one-hot), 192 dims for real UNSW-NB15 (more proto/service/state values).")
w("- Crypto flow: sender makes an ephemeral P-256 key pair, ECDH with the cloud's long-term public key, HKDF-SHA256 (info `cipherguard-shield-v1`, no salt) -> 32-byte AES key, AES-256-GCM with 12-byte random nonce; tag (16 B) stored separately; wire envelope = ciphertext (same length as plaintext) + 12 B nonce + 16 B tag + 65 B uncompressed ephemeral public key = **93 bytes fixed overhead**. The 'cloud' is an in-process mock with a process-lifetime key pair; the API also caches session keys by ephemeral key (demo shortcut) and falls back to real ECDH with the cloud private key when the cache is empty (tested).")
w("- **No database.** Alerts are an in-memory list capped at 500 (lost on restart); model/report artefacts are files. The ER diagram therefore shows logical entities, not tables.")
w("- Limits enforced: text <=1 MB, file <=5 MB, CSV <=10 MB and <=10,000 rows; non-CSV, empty, malformed base64, missing ephemeral key and tag mismatch return 400; engine missing -> 503. CORS `*`, no authentication, no TLS in the demo.")
w("- Lines of code: cipherguard 1,464 (api 382, crypto 163, ids 919, incl. __init__ files), scripts (original) 247, tests 250, web legacy 566 (html 166, js 260, css 140), React console source 3,210 lines (pages, components, libs). Added in this documentation run: scripts/run_experiments.py, benchmark_crypto.py, measure_pipeline.py, make_real_bundle.py, fetch_unsw_nb15.py, capture_real_screens.py, serve.py, tests/*.\n")
w("### Endpoints\n")
for e in ["GET /api/health", "GET /api/metrics", "POST /api/ids/score", "POST /api/ids/score-batch (multipart CSV)", "GET /api/alerts?limit=", "DELETE /api/alerts", "POST /api/crypto/encrypt", "POST /api/crypto/decrypt", "POST /api/crypto/encrypt-file (multipart)", "GET /docs, /openapi.json, / (legacy dashboard)"]:
    w(f"- {e}")
w("\nReact routes: `/` landing, `/app` live scoring (+ batch + session charts), `/app/secure`, `/app/alerts`, `/app/performance`.\n")

w("## 3. Data\n")
w("- **Shipped model (what the app runs by default):** trained on a **synthetic** 12,000-row dataset (6,000 normal + 6,000 attack) generated by `cipherguard/ids/synthetic.py` with the UNSW-NB15 *schema* (42 features) - not real traffic. Split stratified 70/15/15 = 8,400 / 1,800 / 1,800 (seed 42). 2.5 % label noise (300 flipped rows) is injected, so accuracy cannot exceed about 0.975 if the clean classes were separable; `attack_cat` of attack rows is drawn with an unseeded `np.random.choice` (not reproducible).")
w("- **Real data used for the experiments:** UNSW-NB15 (Moustafa & Slay, UNSW Canberra Cyber Range Lab, 2015). Official partition: training set 175,341 flows (56,000 normal / 119,341 attack), testing set 82,332 flows (37,000 normal / 45,332 attack = 55.06 % attack). Obtained via the Hugging Face repackaging `lacg030175/UNSW-NB15` (config `standard`, CC-BY-4.0 packaging; original data free for academic use with citation). Same 42 features as the app. Attack categories: Normal, Generic, Exploits, Fuzzers, DoS, Reconnaissance, Analysis, Backdoor, Shellcode, Worms.")
w("- Train/test of the official partition are **temporally separated** (different capture periods), which is harder than a random split.")
w("- Base paper's data: 9,000 balanced samples (4,500 per class) of UNSW-NB15, stratified 70/15/15, 10 repetitions, averages reported.\n")

w("## 4. Metrics\n")
w("### 4.1 Shipped bundle (synthetic data, reports/metrics.json)\n")
cm = shipped["confusion_matrix"]
w(f"Test 1,800 rows: accuracy {shipped['accuracy']:.4f}, precision {shipped['precision']:.4f}, recall {shipped['recall']:.4f}, F1 {shipped['f1']:.4f}, ROC-AUC {shipped['roc_auc']:.4f}; confusion [[TN {cm[0][0]}, FP {cm[0][1]}],[FN {cm[1][0]}, TP {cm[1][1]}]]; XGBoost alone {shipped['xgb_accuracy']:.4f}, CNN alone {shipped['cnn_accuracy']:.4f} (all three identical = classes almost separable by construction); meta weights {shipped['meta_coef'][0][0]:.3f} (XGB) / {shipped['meta_coef'][0][1]:.3f} (CNN), intercept {shipped['meta_intercept'][0]:.3f}.")
f = sh["shipped_on_fresh_synthetic_seed7"]["stack"]
w(f"Fresh synthetic data (seed 7, 6,000 rows): accuracy {f['accuracy']:.4f}, F1 {f['f1']:.4f}.\n")
w("### 4.2 Real UNSW-NB15, official partition (scripts/run_experiments.py, 5 seeds 42-46, mean ± std)\n")
w(f"Fit {off['fit_rows']:,} / validation {off['val_rows']:,} (both from the official training set) / test {off['test_rows']:,} (official testing set). Encoded dims 192. Metrics at threshold 0.5.\n")
w("| Model | Accuracy | Precision | Recall | F1 | ROC-AUC | FPR | MCC |\n|---|---|---|---|---|---|---|---|")
names = {"stack": "**Stacked (shipped design)**", "xgb": "XGBoost alone", "cnn": "1D CNN alone", "mean": "Mean of XGB+CNN", "rf": "Random forest (100 trees, depth 16)", "dt": "Decision tree (depth 12)", "lr": "Logistic regression"}
for k in ["stack", "xgb", "cnn", "mean", "rf", "dt", "lr"]:
    s = off["summary"][k]
    w(f"| {names[k]} | {pm(s,'accuracy')} | {pm(s,'precision')} | {pm(s,'recall')} | {pm(s,'f1')} | {pm(s,'roc_auc')} | {pm(s,'fpr')} | {pm(s,'mcc')} |")
s42 = off["seed42"]["stack"]
w(f"\nSeed 42 stacked confusion matrix (rows actual normal/attack): [[{s42['confusion_matrix'][0][0]:,}, {s42['confusion_matrix'][0][1]:,}], [{s42['confusion_matrix'][1][0]:,}, {s42['confusion_matrix'][1][1]:,}]]; accuracy {s42['accuracy']:.4f}, precision {s42['precision']:.4f}, recall {s42['recall']:.4f}, F1 {s42['f1']:.4f}, AUC {s42['roc_auc']:.4f}, FPR {s42['fpr']:.4f}, FNR {s42['fnr']:.4f}.")
w(f"XGBoost seed-42 confusion {off['seed42']['xgb']['confusion_matrix']}; CNN seed-42 confusion {off['seed42']['cnn']['confusion_matrix']}.")
w("**Finding:** on the official partition XGBoost alone (0.910) beats the stacked ensemble (0.890) and the CNN (0.841); the logistic-regression meta-model is fitted on a validation split drawn from the *training* period, so it inherits the CNN's higher false-alarm rate on the later test period. Stacking improves on the plain mean by only ~0.002.\n")
w("Threshold sweep of the stacked model (seed 42):\n\n| Threshold | Accuracy | Precision | Recall | F1 | FPR |\n|---|---|---|---|---|---|")
for t in off["thresholds"]:
    if t["threshold"] in (0.1, 0.3, 0.5, 0.7, 0.9, 0.95):
        w(f"| {t['threshold']:.2f} | {t['accuracy']:.4f} | {t['precision']:.4f} | {t['recall']:.4f} | {t['f1']:.4f} | {t['fpr']:.4f} |")
best = max(off["thresholds"], key=lambda r: r["f1"])
w(f"\nBest F1 on the sweep: threshold {best['threshold']:.2f} (F1 {best['f1']:.4f}, accuracy {best['accuracy']:.4f}, FPR {best['fpr']:.4f}). The sweep was run on the test set, so it describes the trade-off and is not a tuned result.\n")
w("Per attack category (stacked, seed 42, threshold 0.5): " + "; ".join(f"{k} {v['rate']*100:.1f}% of {v['n']:,}" for k, v in off["per_category"].items()) + ". (Normal = share correctly passed; others = share detected.) Weak spots: normal traffic (22.6 % false alarms) and Fuzzers (13.3 % missed).")
w("XGBoost top features by gain (seed 42): " + ", ".join(f"{n.split('__')[1]} ({g:.0f})" for n, g in off["feature_importance_gain"][:8]) + ". `sttl` dominates (gain ~2,725 vs 170 for the next feature) - a known UNSW-NB15 artefact of the testbed.")
t = off["train_seconds"]
w(f"Training time on the CPU machine (loaded by other processes): XGBoost {t['xgb']:.1f} s, CNN {t['cnn']:.0f} s (149,039 rows).\n")
w("### 4.3 Base-paper protocol (9,000 balanced flows, 70/15/15, 10 repetitions, mean ± std)\n")
w("Test split 1,350 flows per repetition.\n\n| Model | Accuracy | Precision | Recall | F1 | ROC-AUC | FPR |\n|---|---|---|---|---|---|---|")
for k in ["stack", "xgb", "cnn", "mean", "rf", "dt", "lr"]:
    s = pap["summary"][k]
    w(f"| {names[k]} | {pm(s,'accuracy')} | {pm(s,'precision')} | {pm(s,'recall')} | {pm(s,'f1')} | {pm(s,'roc_auc')} | {pm(s,'fpr')} |")
w("\nBase paper reports (UNSW-NB15, 9,000 balanced samples, 70/15/15, 10 runs): proposed FLPF-EVD-QNN+LeNet accuracy 0.95638 (ablation, TD=80 %), mean accuracy 0.948696 (Table 2), precision 0.97 at TD=90 %, FPR 0.03; baselines QNN+ECC 0.90492, QAE 0.904385, PolyNet 0.905035, LinkNet 0.912707, Bi-LSTM 0.899314, SqueezeNet 0.935426, LeNet 0.906939. EECC encryption 0.39 s, decryption 0.26 s, latency 0.645 (units/data size as in the paper; not comparable with our per-message times). The paper's exact sampled subset and test fraction are not published, so this is a *comparable protocol*, not an identical experiment: our stack reaches 0.938 accuracy (0.934 precision, FPR 0.067): about 1 point below the paper's proposed model (mean accuracy 0.9487), 3.6 points below its quoted precision of 0.97, and slightly above the best of its re-implemented baselines (SqueezeNet 0.9354). Both are subsets of the same source dataset, so this is indicative only.\n")
w("### 4.4 Domain shift (experiments/unsw_nb15/shift)\n")
r = sh["shipped_on_real_official_test"]
w(f"- Shipped (synthetic-trained) models on the 82,332 real test flows: stacked accuracy {r['stack']['accuracy']:.4f}, precision {r['stack']['precision']:.4f}, recall {r['stack']['recall']:.4f}, F1 {r['stack']['f1']:.4f}, ROC-AUC {r['stack']['roc_auc']:.4f}, MCC {r['stack']['mcc']:.3f}; XGB alone {r['xgb']['accuracy']:.4f}, CNN alone {r['cnn']['accuracy']:.4f}. Barely better than chance - the synthetic model has not learned real traffic.")
r2 = sh["real_trained_on_synthetic_demo_csv"]["stack"]
w(f"- Real-trained (official seed 42) models on the synthetic demo CSV (12,000 rows): accuracy {r2['accuracy']:.4f}, ROC-AUC {r2['roc_auc']:.4f} (below chance: the generator's distributions differ from, and in places invert, real UNSW-NB15 patterns).")
w("- In the app (screens 10 and 12) a 120-flow real sample (60 normal / 60 attack, `data/samples/real_unsw_nb15_sample_120.csv`) is scored: shipped model flags 66 attacks and agrees with the labels on 78/120 (65.0 %); real-trained bundle flags 73 attacks and agrees on 101/120 (84.2 %).\n")

w("## 5. Cryptography and latency (experiments/crypto, experiments/pipeline)\n")
w(f"Machine: Intel Core i5-12500 (6 cores / 12 threads), 15.7 GB RAM, Windows 11, Python {cry['machine']['python']}, cryptography {cry['machine']['cryptography']}. Medians over repeated runs (reps in JSON); the machine was shared with other jobs, so treat absolute values as indicative.\n")
w("| Payload | SecureChannel enc (ms) | SecureChannel dec (ms) | AES-256-GCM only enc / dec (ms) | RSA-2048-OAEP+AES enc / dec (ms) | RSA-3072-OAEP+AES enc / dec (ms) |\n|---|---|---|---|---|---|")
for k in ["1 KB", "10 KB", "100 KB", "1 MB", "5 MB"]:
    a, b, c, d = cry["secure_channel_ecdh_aesgcm"][k], cry["aes256gcm_only"][k], cry["rsa2048_oaep_aesgcm"]["sizes"][k], cry["rsa3072_oaep_aesgcm"]["sizes"][k]
    w(f"| {k} | {a['encrypt']['median_ms']:.3f} | {a['decrypt']['median_ms']:.3f} | {b['encrypt']['median_ms']:.3f} / {b['decrypt']['median_ms']:.3f} | {c['encrypt']['median_ms']:.3f} / {c['decrypt']['median_ms']:.3f} | {d['encrypt']['median_ms']:.3f} / {d['decrypt']['median_ms']:.3f} |")
w(f"\nSecureChannel timings include the ephemeral key generation, ECDH, HKDF and **base64 encoding/decoding of the payload** (the API returns base64), which is why large payloads cost more than raw AES-GCM (AES-GCM alone ~1.3 GB/s at 1-5 MB; SecureChannel ~235 MB/s). ECDH P-256 key generation {cry['key_setup']['ecdh_p256_keygen']['median_ms']*1000:.0f} us; ECDH + HKDF {cry['key_setup']['ecdh_exchange_plus_hkdf']['median_ms']*1000:.0f} us; RSA-2048 key generation {cry['rsa2048_oaep_aesgcm']['keygen_ms_one_time']:.0f} ms and RSA-3072 {cry['rsa3072_oaep_aesgcm']['keygen_ms_one_time']:.0f} ms (one-time, single sample). RSA decrypt (key unwrap) costs 0.45 ms (2048) / 1.4 ms (3072) per message versus 0.05 ms for the ECDH + HKDF step; RSA encrypt is cheaper (0.03-0.04 ms) because the public exponent is small. Wrapped-key size 256 B (RSA-2048) vs 65 B ephemeral point (P-256).")
w("Tamper tests (1,000 trials each): untouched accepted 1000/1000; ciphertext bit flip rejected 1000/1000; tag bit flip 1000/1000; nonce bit flip 1000/1000; ciphertext truncated by one byte 1000/1000; decryption with another party's key 1000/1000. 20,000 encryptions of one plaintext gave 20,000 distinct nonces and 20,000 distinct ciphertexts.")
ip, ap = pipe["in_process"], pipe["api_127_0_0_1"]
w(f"\nIn-process protected transfer of a 100 KB payload (score 1 flow + encrypt + decrypt), median: IDS scoring {ip['ids_score_single']['median_ms']:.2f} ms, encrypt {ip['encrypt_100kb']['median_ms']:.2f} ms, decrypt {ip['decrypt_100kb']['median_ms']:.2f} ms, total {ip['protected_transfer_100kb']['median_ms']:.2f} ms (p95 {ip['protected_transfer_100kb']['p95_ms']:.2f}); IDS share of the total {ip['share_of_transfer_median']['ids']*100:.0f} %, encryption {ip['share_of_transfer_median']['encrypt']*100:.0f} %, decryption {ip['share_of_transfer_median']['decrypt']*100:.0f} %. Batch scoring: 120 rows {ip['ids_batch_120_rows']['median_ms']:.1f} ms, 1,000 rows {ip['ids_batch_1000_rows']['median_ms']:.1f} ms. Engine load {ip['engine_load_ms']:.0f} ms.")
w("HTTP API on 127.0.0.1 (median / p95 ms): " + "; ".join(f"{k} {v['median_ms']:.2f} / {v['p95_ms']:.2f}" for k, v in ap.items()) + ".")
w(f"Real-trained bundle inference (192-dim, in-process, official seed 42): 1 flow {off['inference_timing_ms']['1']['median_ms']:.2f} ms, 100 flows {off['inference_timing_ms']['100']['median_ms']:.1f} ms, 1,000 flows {off['inference_timing_ms']['1000']['median_ms']:.1f} ms.\n")

